module RAM_74189 (output S4, S3, S2, S1, input D4, D3, D2, D1, A3, A2, A1, A0, CS, WE);// Note: active-low CS and WE  wire [3: 0] 				address = {A3, A2, A1, A0};   reg [3: 0] 				RAM [0: 15];			// 16 x 4 memory  wire [4: 1] 				Data_in = { D4, D3, D2, D1};	// Input word  tri [4: 1] 					Data;				// Output data word, three-state output  assign S1 = Data[1];			// Output bits  assign S2 = Data[2];  assign S3 = Data[3];  assign S4 = Data[4];  always @ (Data_in, address, CS, WE) if (~CS && ~WE) RAM[address] = Data_in;  assign Data = (~CS && WE) ? ~RAM[address] : 4'bz; endmodulemodule t_RAM_74189 ();  reg [4: 1] Data_in;  reg [3: 0] address;  reg CS, WE;  wire S1, S2, S3, S4;  wire D1, D2, D3, D4;  wire A0, A1, A2, A3;  wire [4: 1] Data_out = {S4, S3, S2, S1};  assign  D1 = Data_in [1];  assign  D2 = Data_in [2];  assign  D3 = Data_in [3];  assign  D4 = Data_in [4];  assign A0 = address[0];  assign A1 = address[1];  assign A2 = address[2];   assign A3 = address[3];   wire [3: 0] RAM_0 = M0.RAM[0];  wire [3: 0] RAM_1 = M0.RAM[1];  wire [3: 0] RAM_2 = M0.RAM[2];  wire [3: 0] RAM_3 = M0.RAM[3];  wire [3: 0] RAM_4 = M0.RAM[4];  wire [3: 0] RAM_5 = M0.RAM[5];  wire [3: 0] RAM_6 = M0.RAM[6];  wire [3: 0] RAM_7 = M0.RAM[7];  wire [3: 0] RAM_8 = M0.RAM[8];  wire [3: 0] RAM_9 = M0.RAM[9];  wire [3: 0] RAM_10 = M0.RAM[10];  wire [3: 0] RAM_11 = M0.RAM[11];  wire [3: 0] RAM_12= M0.RAM[12];  wire [3: 0] RAM_13 = M0.RAM[13];  wire [3: 0] RAM_14 = M0.RAM[14];  wire [3: 0] RAM_15 = M0.RAM[15];  wire [4: 1] word = ~Data_out;  RAM_74189 M0 (S4, S3, S2, S1, D4, D3, D2, D1, A3, A2, A1, A0, CS, WE);  initial #110 $finish;  initial fork    WE = 1;    CS = 1;     address = 0;    Data_in = 3;    #10 CS = 0;    #15 WE = 0;    #20 WE = 1;    #25 address = 14;    #25 Data_in = 1;    #30 WE = 0;    #35 WE = 1;    #40 CS = 1;    #50 address = 0;    #60 CS = 0;    #70 CS = 1;    #80 address = 14;    #90 CS = 0;  join endmodule